-- SHELFIE: keep the current recommendation set stable between page loads.
-- A new set is generated by an explicit refresh, a new browser session, or
-- when the cached set is older than six hours.
begin;

create table if not exists public.ai_recommendation_cache (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  books jsonb not null default '[]'::jsonb,
  generated_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint ai_recommendation_cache_books_array
    check (jsonb_typeof(books) = 'array'),
  constraint ai_recommendation_cache_books_limit
    check (jsonb_array_length(books) <= 6)
);

alter table public.ai_recommendation_cache enable row level security;
revoke all on public.ai_recommendation_cache from public, anon, authenticated;

create or replace function public.save_my_ai_recommendations(p_books jsonb)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.ai_recommendation_preferences
    where user_id = auth.uid() and personalization_enabled = true
  ) then
    raise exception 'Personalization is disabled' using errcode = '42501';
  end if;

  if p_books is null or jsonb_typeof(p_books) <> 'array' then
    raise exception 'Invalid recommendation set' using errcode = '22023';
  end if;

  if jsonb_array_length(p_books) > 6 then
    raise exception 'Recommendation set is too large' using errcode = '22023';
  end if;

  insert into public.ai_recommendation_cache(user_id, books, generated_at, updated_at)
  values (auth.uid(), p_books, now(), now())
  on conflict (user_id) do update set
    books = excluded.books,
    generated_at = now(),
    updated_at = now();
end; $$;

create or replace function public.get_my_ai_recommendation_cache()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.ai_recommendation_preferences
    where user_id = auth.uid() and personalization_enabled = true
  ) then
    return jsonb_build_object('books', '[]'::jsonb, 'generated_at', null, 'stale', false, 'complete', false);
  end if;

  select jsonb_build_object(
    'books', coalesce((
      select jsonb_agg(book order by ordinality)
      from jsonb_array_elements(c.books) with ordinality as entries(book, ordinality)
      where not exists (
        select 1 from public.ai_recommendation_dismissals d
        where d.user_id = auth.uid()
          and d.google_books_id = book->>'google_books_id'
      )
    ), '[]'::jsonb),
    'generated_at', c.generated_at,
    'complete', jsonb_array_length(c.books) = 6,
    'stale', c.generated_at <= now() - interval '6 hours'
  )
  into result
  from public.ai_recommendation_cache c
  where c.user_id = auth.uid();

  return coalesce(result, jsonb_build_object(
    'books', '[]'::jsonb,
    'generated_at', null,
    'stale', true,
    'complete', false
  ));
end; $$;

revoke all on function public.save_my_ai_recommendations(jsonb) from public, anon;
revoke all on function public.get_my_ai_recommendation_cache() from public, anon;
grant execute on function public.save_my_ai_recommendations(jsonb) to authenticated;
grant execute on function public.get_my_ai_recommendation_cache() to authenticated;

commit;
